// Offline only: package recordings generated by the browser harness. No user audio.
// node scripts/package-tour-audio.mjs /absolute/path/to/voice-lab-vocoloco
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';import ts from 'typescript';import vm from 'node:vm';
const lab=process.argv[2];if(!lab)throw Error('Provide the offline voice-lab directory.');
const context={exports:{}};vm.runInNewContext(ts.transpileModule(fs.readFileSync('lib/speech.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,context);
const {spokenText}=context.exports,manifest={};const previous=JSON.parse(fs.readFileSync('public/tour-audio/manifest.json','utf8')); fs.mkdirSync('public/tour-audio',{recursive:true});
for(const {name,text,lang} of JSON.parse(fs.readFileSync(path.join(lab,'tour-jobs.json'),'utf8'))){
 const input=path.join(lab,'results',name+'.wav');if(!fs.existsSync(input)){if(process.argv.includes('--partial'))continue;throw Error('Missing recording '+name)}
 const key=JSON.stringify([lang,'F1',spokenText(text)]),hash=crypto.createHash('sha256').update(key).update(fs.readFileSync(input)).digest('hex').slice(0,20),url='/tour-audio/'+hash+'.mp3';
 if(!fs.existsSync('public'+url))execFileSync('ffmpeg',['-y','-v','error','-i',input,'-codec:a','libmp3lame','-b:a','64k','public'+url]);manifest[key]=url;
}
fs.writeFileSync('public/tour-audio/manifest.json',JSON.stringify(manifest,null,2)+'\n');console.log('Packaged',Object.keys(manifest).length,'tour recordings.');

for(const url of Object.values(previous)){if(/^\/tour-audio\/[a-f0-9]{20}\.mp3$/.test(url)&&!Object.values(manifest).includes(url))fs.rmSync('public'+url,{force:true})}
